    const registry = new ToolRegistry();
    let executorCalls = 0;
    let executorInput: Record<string, unknown> | undefined;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test',
        inputSchema: {
          type: 'object',
          properties: {
            req: {type: 'string'},
          },
          required: ['req'],
        },
      },
      async input => {
        executorCalls++;
        executorInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {req: 'value', extra: 123});

    expect(executorCalls).toBe(1);
    expect(executorInput).toEqual({req: 'value', extra: 123});
  });
});
